import React from 'react';
import { Link } from 'gatsby';
import kebabCase from 'lodash/kebabCase';
import Post from '../models/Post';
import * as styles from './PrevNext.module.scss';

interface Props {
  next: Post;
  prev: Post;
  theme?: {
    colors: {
      primary: string;
      grey: {
        light: string;
      };
    };
  };
}

const PrevNext = (props: Props) => {
  const { prev, next, theme } = props;

  const styleVars: React.CSSProperties = {
    ['--prevnext-link-color' as any]: theme?.colors.primary,
    ['--prevnext-label-color' as any]: theme?.colors.grey.light,
  };

  return (
    <div className={styles.wrapper} style={styleVars}>
      {prev && (
        <div className={styles.prev}>
          <span>Previous</span>
          <Link to={`/blog/${kebabCase(prev.frontmatter.title)}`}>{prev.frontmatter.title}</Link>
        </div>
      )}
      {next && (
        <div className={styles.next}>
          <span>Next</span>
          <Link to={`/blog/${kebabCase(next.frontmatter.title)}`}>{next.frontmatter.title}</Link>
        </div>
      )}
    </div>
  );
};

export default PrevNext;
