import React from 'react';
import { Link, graphql } from 'gatsby';
import kebabCase from 'lodash/kebabCase';
import PathContext from '../models/PathContext';
import { Post } from '../../types';
import { Date } from '../components/Date';
import PageTitle from '../components/PageTitle';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import Header from '../components/Header';
import SectionTitle from '../components/SectionTitle';
import Subline from '../components/Subline';
import Wrapper from '../components/Wrapper';
import Content from '../components/Content';
import PrevNext from '../components/PrevNext';
import styles from './Post.module.scss';

interface Props {
  data: {
    markdownRemark: Post;
  };
  pageContext: PathContext;
}

export default class PostPage extends React.PureComponent<Props> {
  public render() {
    const { prev, next } = this.props.pageContext;
    const post = this.props.data.markdownRemark;
    return (
      <Layout>
        {post ? (
          <>
            <SEO postPath={post.fields.slug} postNode={post} postSEO />
            <PageTitle title={post.frontmatter.title} />

            <Header banner={post.frontmatter.banner}>
              <SectionTitle>{post.frontmatter.title}</SectionTitle>
              <Subline light={false}>
                <Date date={post.frontmatter.date} />
                <br />
                {post.timeToRead} Min Read
                <br />
                <Link to={`/categories/${kebabCase(post.frontmatter.category)}`}>{post.frontmatter.category}</Link>
              </Subline>
            </Header>
            <Wrapper>
              <Content>
                <div className={styles.postContent} dangerouslySetInnerHTML={{ __html: post.html }} />
                {post.frontmatter.tags ? (
                  <Subline>
                    Tags: &#160;
                    {post.frontmatter.tags.map((tag, i) => (
                      <Link key={i} to={`/tags/${kebabCase(tag)}`}>
                        <strong>{tag}</strong> {i < post.frontmatter.tags.length - 1 ? `, ` : ``}
                      </Link>
                    ))}
                  </Subline>
                ) : null}
                <PrevNext prev={prev} next={next} />
              </Content>
            </Wrapper>
          </>
        ) : null}
      </Layout>
    );
  }
}

export const postQuery = graphql`
  query ($slug: String!) {
    markdownRemark(fields: { slug: { eq: $slug } }) {
      html
      fields {
        slug
      }
      frontmatter {
        title
        date(formatString: "DD.MM.YYYY")
        category
        tags
        banner
      }
      timeToRead
    }
  }
`;
